import { useState } from 'react';
import { PenTool, CheckSquare, Plus, CheckCircle2, Trash2, CalendarDays, MapPin, Clock, Sparkles, Loader2 } from 'lucide-react';
import { CATEGORIES } from '../constants';
import { formatYMD } from '../utils/dateHelpers';
import { generateDailySummary } from '../utils/api';

export default function TodoSection({
    selectedDate, diaries, saveDiary,
    todos, addTodo, toggleTodo, deleteTodo, newTodo, setNewTodo, celebratingId,
    searchQuery, displayedEvents, deleteEvent,
    setNewEventDate, setShowAddModal,
    pomoSessions, currentMood, weatherData
}) {
    const [isGenerating, setIsGenerating] = useState(false);

    // ?뱷 AI ?섎（ ?붿빟 ?앹꽦
    const handleAISummary = async () => {
        if (isGenerating) return;
        setIsGenerating(true);
        try {
            const dateStr = formatYMD(selectedDate);
            const todaySessions = (pomoSessions || []).filter(s => s.date === dateStr);
            const weatherDesc = weatherData?.weather?.[0]?.description || '';

            const result = await generateDailySummary({
                tomatoes: todaySessions.length,
                sessions: todaySessions,
                todos: todos || [],
                mood: currentMood || '?대옒??,
                weather: weatherDesc,
                diary: diaries[dateStr] || '',
            });

            if (result.summary) {
                const existing = diaries[dateStr] || '';
                const divider = existing ? '\n\n--- ?뱷 AI ?붿빟 ---\n' : '?뱷 AI ?붿빟\n';
                saveDiary(existing + divider + result.summary);
            } else {
                alert(result.error || 'AI ?붿빟 ?앹꽦???ㅽ뙣?덉뼱??');
            }
        } catch (err) {
            alert('AI ?붿빟 ?앹꽦 以??ㅻ쪟媛 諛쒖깮?덉뼱??');
        } finally {
            setIsGenerating(false);
        }
    };

    return (
        <>
            {/* Daily Retrospective (?ㅻ뒛????빐 ?쇱?) */}
            <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800">
                <h3 className="text-xl font-black mb-4 flex items-center gap-3 text-indigo-600 dark:text-indigo-400">
                    <PenTool className="w-6 h-6" /> ?ㅻ뒛????빐 ?쇱?
                </h3>
                <p className="text-xs text-slate-400 mb-4 font-bold">{selectedDate.toLocaleDateString('ko-KR', { month: 'long', day: 'numeric' })}??湲곕줉</p>
                <textarea
                    placeholder="?ㅻ뒛 ?섎（???대븷?섏슂? ?ъ냼??移?갔?? ?꾩돩???먮룄 紐⑤몢 蹂꾨튆????嫄곗삁??"
                    className="w-full h-32 p-4 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl text-sm text-slate-800 dark:text-slate-100 focus:ring-2 focus:ring-indigo-500 outline-none resize-none leading-relaxed transition-all placeholder-slate-400 custom-scrollbar"
                    value={diaries[formatYMD(selectedDate)] || ''}
                    onChange={(e) => saveDiary(e.target.value)}
                />
                <button
                    onClick={handleAISummary}
                    disabled={isGenerating}
                    className={`mt-3 w-full flex items-center justify-center gap-2 py-3 rounded-2xl font-bold text-sm transition-all cursor-pointer
                        ${isGenerating
                            ? 'bg-indigo-100 dark:bg-indigo-900/30 text-indigo-400 cursor-wait'
                            : 'bg-gradient-to-r from-indigo-500 to-purple-500 text-white hover:from-indigo-600 hover:to-purple-600 shadow-lg shadow-indigo-200/50 dark:shadow-indigo-900/30 hover:scale-[1.02] active:scale-95'
                        }
                    `}
                >
                    {isGenerating ? (
                        <><Loader2 className="w-4 h-4 animate-spin" /> AI媛 ?ㅻ몢留됱쓽 湲곗뼲???곌퀬 ?덉뼱??..</>
                    ) : (
                        <><Sparkles className="w-4 h-4" /> ?뱷 AI ?섎（ ?붿빟 ?곌린</>
                    )}
                </button>
            </div>

            {/* Daily To-Do ?럦 ??＝ ?좊땲硫붿씠??異붽???*/}
            <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800 relative">
                <h3 className="text-xl font-black mb-6 flex items-center gap-3"><CheckSquare className="w-6 h-6 text-green-500" /> ?ㅻ뒛 ?섏쓽 紐⑺몴</h3>
                <form onSubmit={addTodo} className="mb-6 flex gap-2">
                    <input type="text" placeholder="?ㅻ뒛 ????.." className="flex-1 px-4 py-2.5 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl text-sm text-slate-800 dark:text-slate-100 focus:ring-2 focus:ring-green-500 outline-none" value={newTodo} onChange={(e) => setNewTodo(e.target.value)} />
                    <button type="submit" className="bg-green-600 text-white p-2.5 rounded-2xl hover:bg-green-700 transition-all cursor-pointer"><Plus className="w-5 h-5" /></button>
                </form>
                <div className="space-y-3">
                    {todos.map(todo => (
                        <div key={todo.id} className="relative flex items-center gap-3 p-3 rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors group">
                            {/* ?럦 ??＝ ?뚰떚 ?④낵 */}
                            {celebratingId === todo.id && (
                                <div className="absolute left-2 -top-4 pointer-events-none z-50 flex gap-1 text-2xl">
                                    <span className="confetti-anim" style={{ animationDelay: '0ms' }}>?럦</span>
                                    <span className="confetti-anim" style={{ animationDelay: '100ms' }}>??/span>
                                    <span className="confetti-anim" style={{ animationDelay: '200ms' }}>?럧</span>
                                </div>
                            )}
                            <div onClick={() => toggleTodo(todo.id)} className={`w-5 h-5 rounded-md border-2 flex items-center justify-center transition-all cursor-pointer flex-shrink-0 z-10 ${todo.completed ? 'bg-green-500 border-green-500' : 'border-slate-300'}`}>
                                {todo.completed && <CheckCircle2 className="w-3 h-3 text-white" />}
                            </div>
                            <span onClick={() => toggleTodo(todo.id)} className={`text-sm font-medium transition-all flex-1 cursor-pointer z-10 ${todo.completed ? 'line-through text-slate-400' : 'text-slate-700 dark:text-slate-300'}`}>{todo.text}</span>
                            <button onClick={() => deleteTodo(todo.id)} className="cursor-pointer text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity z-10"><Trash2 className="w-4 h-4" /></button>
                        </div>
                    ))}
                    {todos.length === 0 && <p className="text-center text-sm text-slate-400 py-4">紐⑤뱺 ???쇱쓣 留덉낀嫄곕굹, ?꾩쭅 ?녿꽕?? ??/p>}
                </div>
            </div>

            {/* Schedule Info */}
            <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800">
                <div className="flex justify-between items-center mb-8">
                    <h3 className="font-black text-lg flex items-center gap-2 text-blue-600 dark:text-blue-400">
                        <CalendarDays className="w-5 h-5" />
                        {searchQuery.trim() ? '寃??寃곌낵' : selectedDate.toLocaleDateString('ko-KR', { month: 'long', day: 'numeric' })}
                    </h3>
                    <button onClick={() => { setNewEventDate(formatYMD(selectedDate)); setShowAddModal(true); }} className="p-2 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-xl hover:scale-110 transition-transform cursor-pointer"><Plus className="w-5 h-5" /></button>
                </div>

                <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                    {displayedEvents.length > 0 ? (
                        displayedEvents.map(event => (
                            <div key={event.id} className="p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-700 relative group">
                                <div className="flex justify-between items-start mb-2">
                                    <span className={`text-[10px] font-black px-3 py-1 rounded-full uppercase inline-block ${CATEGORIES.find(c => c.id === event.category)?.color || CATEGORIES[4].color}`}>
                                        {CATEGORIES.find(c => c.id === event.category)?.name || '湲고?'}
                                    </span>
                                    <button onClick={() => deleteEvent(event.id)} className="cursor-pointer text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 className="w-4 h-4" /></button>
                                </div>
                                <h4 className="font-black text-slate-800 dark:text-slate-200 mb-2 leading-tight pr-4">{event.title}</h4>
                                <div className="flex flex-col gap-1.5 text-[11px] text-slate-500 dark:text-slate-400 font-bold">
                                    <div className="flex items-center gap-2"><MapPin className="w-3.5 h-3.5 text-blue-400" /> {event.location}</div>
                                    <div className="flex items-center gap-2">
                                        <Clock className="w-3.5 h-3.5 text-orange-400" />
                                        {event.date} {event.time && <span className="text-slate-400 dark:text-slate-500 ml-1 opacity-80">{event.time}</span>}
                                    </div>
                                </div>
                            </div>
                        ))
                    ) : (
                        <div className="py-16 text-center text-slate-300 dark:text-slate-700">
                            <CheckCircle2 className="w-12 h-12 mx-auto mb-4 opacity-30" />
                            <p className="text-xs font-black uppercase tracking-widest">{searchQuery.trim() ? '寃?됰맂 ?쇱젙???놁뼱?? : '?쇱젙???녿뒗 ?몄븞????}</p>
                        </div>
                    )}
                </div>
            </div>
        </>
    );
}

export const CATEGORIES = [
    { id: 'all', name: '?꾩껜', color: 'bg-slate-200 text-slate-700' },
    { id: 'exam', name: '?쒗뿕/梨꾩슜', color: 'bg-blue-100 text-blue-700' },
    { id: 'event', name: '?됱궗/異뺤젣', color: 'bg-purple-100 text-purple-700' },
    { id: 'welfare', name: '蹂듭?/?쒗깮', color: 'bg-green-100 text-green-700' },
    { id: 'other', name: '湲고?', color: 'bg-orange-100 text-orange-700' },
];

export const WEEKDAYS = ['??, '??, '??, '??, '紐?, '湲?, '??];

export const DEFAULT_QUOTES = [
    "媛???대몢??諛ㅻ룄 寃곌뎅 吏?섍?怨??대뒗 ??寃껋씠??",
    "?뱀떊???몃젰???ㅻ뒛???뱀떊??留뚮뱺??",
    "泥쒖쿇??媛??寃껋쓣 ?먮젮??留먭퀬, 硫덉텛??寃껋쓣 ?먮젮?뚰븯??",
    "?묒? ?깆랬媛 紐⑥뿬 嫄곕????깃났???대，??",
    "?ㅻ뒛???諛⑹슱? ?댁씪???껋쓬苑껋씠 ?쒕떎."
];

export const SUBJECT_COLORS = [
    { id: 'red', value: 'bg-red-400' },
    { id: 'orange', value: 'bg-orange-400' },
    { id: 'yellow', value: 'bg-yellow-400' },
    { id: 'green', value: 'bg-green-400' },
    { id: 'blue', value: 'bg-blue-400' },
    { id: 'purple', value: 'bg-purple-400' },
    { id: 'pink', value: 'bg-pink-400' },
];

export const MOODS = {
    classic: { name: '?대옒???ㅻ몢留?, icon: '?룪', bgImage: '/img/night.png', defaultSound: '?쒓뎅 ?낆꽌??mp3', workBg: 'from-slate-800 to-slate-900 dark:from-slate-900 dark:to-black', restBg: 'from-teal-500 to-cyan-600' },
    rainy: { name: '鍮??ㅻ뒗 ?쒖옱', icon: '?뙢截?, bgImage: '/img/rain.png', defaultSound: '鍮꾩? 泥쒕뫁.wav', workBg: 'from-blue-900 to-slate-800 dark:from-slate-900 dark:to-blue-900', restBg: 'from-blue-500 to-indigo-600' },
    campfire: { name: '?쒕갇??罹좏봽?뚯씠??, icon: '?뵦', bgImage: '/img/fireplace.png', defaultSound: '踰쎈궃濡?mp3', workBg: 'from-orange-900 to-red-900 dark:from-stone-900 dark:to-red-900', restBg: 'from-orange-600 to-red-700' },
    forest: { name: '源딆? ?뀁냽', icon: '?뙯', bgImage: '/img/forest.png', defaultSound: '?뀁뿉 ??1.mp3', workBg: 'from-emerald-900 to-green-900 dark:from-green-900 dark:to-black', restBg: 'from-emerald-500 to-teal-600' }
};

// --- Phase 16: ?ㅻ몢留됱쓽 誘몃옒 (怨꾩젅 諛??뺤썝 由ъ냼?? ---

// 1. 4怨꾩젅 諛곌꼍?붾㈃ 留ㅽ븨
export const SEASONS = {
    spring: { id: 'spring', name: '?붿궗??遊꾨궇', image: '/bg/spring.png', months: [3, 4, 5] },
    summer: { id: 'summer', name: '吏숈? ?뱀쓬???щ쫫', image: '/bg/summer.png', months: [6, 7, 8] },
    autumn: { id: 'autumn', name: '?몄뒪?ㅼ쭅 媛??, image: '/bg/autumn.png', months: [9, 10, 11] },
    winter: { id: 'winter', name: '?ш렐??寃⑥슱 ?꾩묠', image: '/bg/winter.png', months: [12, 1, 2] }
};

// 2. ?뺤썝 4?④퀎 蹂??留ㅽ븨 (?좊쭏??
export const GARDEN_STAGES = [
    { level: 1, name: '?⑥븮 (Seed)', image: '/garden/tomato_1.png', requiredPomos: 0 },
    { level: 2, name: '?덉떦 (Sprout)', image: '/garden/tomato_2.png', requiredPomos: 4 }, // 戮紐⑤룄濡?4踰??ъ꽦
    { level: 3, name: '以꾧린? ??(Plant)', image: '/garden/tomato_3.png', requiredPomos: 10 }, // 10踰??ъ꽦
    { level: 4, name: '?좊쭏???섑솗 (Harvest)', image: '/garden/tomato_4.png', requiredPomos: 20 } // 20踰??ъ꽦
